import functools
import time

def retry(func):
    """
    A decorator that retries a function up to 3 times if it raises an exception.

    Args:
        func (callable): The function to be decorated.

    Returns:
        callable: The wrapped function with retry logic.
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        max_attempts = 3
        last_exception = None

        for attempt in range(1, max_attempts + 1):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                last_exception = e
                print(f"Attempt {attempt} failed: {e}")
                if attempt < max_attempts:
                    print("Retrying...")
                    # Small delay to allow for transient issues to resolve
                    time.sleep(0.5)
                else:
                    print("All attempts failed.")

        # Re-raise the last exception if all attempts are exhausted
        raise last_exception

    return wrapper

# --- Testing the decorator ---

if __name__ == "__main__":
    # 1. Test case: A function that fails twice and then succeeds
    counter = 0

    @retry
    def volatile_function():
        global counter
        counter += 1
        if counter < 3:
            raise ValueError("Temporary failure!")
        return "Success!"

    print("Testing volatile_function (should succeed on 3rd attempt):")
    try:
        result = volatile_function()
        print(f"Result: {result}\n")
    except Exception as e:
        print(f"Final Error: {e}\n")

    # 2. Test case: A function that fails every time
    @retry
    def failing_function():
        raise RuntimeError("Permanent failure!")

    print("Testing failing_function (should fail after 3 attempts):")
    try:
        failing_function()
    except Exception as e:
        print(f"Caught expected final exception: {e}")
